function nightFactor(h) {
  let night = 0, dusk = 0;
  if (h >= 17 && h < 20) { night = (h - 17) / 3 * .5; dusk = clamp(1 - Math.abs(h - 18.3) / 2.2, 0, 1); }
  else if (h >= 20 || h < 5) night = .5;
  else if (h >= 5 && h < 7) { night = .5 * (1 - (h - 5) / 2); dusk = clamp((h - 5) / 2 * .7, 0, .7); }
  return { night, dusk };
}

